<?php
require_once __DIR__.'/../config/bootstrap.php'; require_role('administrador');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$decision=$_POST['decision']??'';$hours=(int)($_POST['horas']??24);$s=$pdo->prepare("SELECT * FROM solicitudes_reapertura WHERE id=? AND estado='pendiente'");$s->execute([$id]);$req=$s->fetch();if($req&&in_array($decision,['aprobada','rechazada'],true)&&($decision!=='aprobada'||($hours>=1&&$hours<=168))){$pdo->beginTransaction();try{$s=$pdo->prepare('UPDATE solicitudes_reapertura SET estado=?,decidido_por=?,decidido_en=NOW(),horas_concedidas=?,decision_nota=? WHERE id=?');$s->execute([$decision,(int)current_user()['id'],$decision==='aprobada'?$hours:0,trim($_POST['decision_nota']??''),$id]);if($decision==='aprobada'){$due=(new DateTimeImmutable('now'))->modify("+{$hours} hours")->format('Y-m-d H:i:s');$s=$pdo->prepare('UPDATE plazos_registro SET vencimiento=?,estado="reabierto",reabierto_por=?,reabierto_en=NOW() WHERE id=?');$s->execute([$due,(int)current_user()['id'],(int)$req['plazo_id']]);}audit($pdo,(int)current_user()['id'],'decision_reapertura',"Solicitud {$id}: {$decision}");$pdo->commit();flash('success','Decisión guardada.');}catch(Throwable $e){$pdo->rollBack();flash('error','No se pudo guardar la decisión.');}}else flash('error','Solicitud no válida o ya resuelta.');redirect('solicitudes.php');}
$rows=$pdo->query('SELECT s.*,u.nombres,u.apellidos,ud.nombre unidad,p.tipo,p.fecha_clase FROM solicitudes_reapertura s JOIN usuarios u ON u.id=s.docente_id JOIN plazos_registro p ON p.id=s.plazo_id JOIN unidades_didacticas ud ON ud.id=p.unidad_id ORDER BY s.creado_en DESC')->fetchAll();
$pageTitle='Solicitudes de reapertura';$assetPrefix='../';require __DIR__.'/../includes/header.php';?>
<div class="dashboard-head"><div><div class="eyebrow">REVISIÓN</div><h1>Solicitudes de reapertura</h1></div><a class="btn secondary" href="index.php">Volver</a></div>
<?php foreach($rows as $r):?><article class="panel request-card"><div class="dashboard-head"><div><span class="status <?= $r['estado']==='pendiente'?'warning':($r['estado']==='aprobada'?'success':'danger')?>"><?= h($r['estado'])?></span><h2><?= h($r['unidad'])?> · <?= h($r['tipo'])?></h2><p class="muted">Docente: <?= h($r['nombres'].' '.$r['apellidos'])?> · Clase: <?= h($r['fecha_clase'])?> · Enviada: <?= h($r['creado_en'])?></p></div></div><blockquote><?= h($r['motivo'])?></blockquote>
<?php if($r['estado']==='pendiente'):?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= h(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$r['id']?>"><div class="field"><label>Horas concedidas si apruebas</label><input type="number" name="horas" min="1" max="168" value="24"></div><div class="field"><label>Nota de decisión</label><input name="decision_nota" maxlength="500"></div><div class="field full"><button class="btn primary" name="decision" value="aprobada">Aprobar</button> <button class="btn danger" name="decision" value="rechazada" data-confirm="¿Rechazar esta solicitud?">Rechazar</button></div></form><?php else:?><p class="hint">Decisión por administrador ID <?= (int)$r['decidido_por']?> · <?= h($r['decidido_en'])?> · <?= (int)$r['horas_concedidas']?> horas concedidas.</p><?php endif;?></article><?php endforeach;?>
